function compactCast595(m,e){const t=String(m.time||'');const ritual=m.ritual===true||/\britual\b/i.test(t)||/Casting Time:[^\n]*\britual\b/i.test(e?.text||'');const base=t.replace(/\s*(?:or|ou)?\s*\(?ritual\)?\s*$/i,'').trim();const short=/^1\s*(minute|minuto|min\.?|m)$/i.test(base)?'1m':base;return ritual?(short?short+' or (R)':'(R)'):short||t;}
